#!/usr/bin/env bash
# scripts/g11_table.sh — ALICE-Law G11 on this repository: every gate alice-law-conformance.toml
# declares pass has a row in conformance/g11.toml naming its checker, the canary it must flag, the
# test that fails when it compared nothing, and the shared-file rows that keep a shared checker identical.
#
# conformance/g11.toml is generated by ALICE-Law's scripts/g11_table_gen.py: the rows of the checkers the
# crates share come from ALICE-Law's conformance/g11-shared-rows.toml, this repository's other rows from
# conformance/g11-own.toml. This script fetches ALICE-Law at the revision .github/g11-table-pin names,
# refuses the generator and the checker unless their SHA-256 are the ones written there, then
#   1. compares conformance/g11.toml with the generated table (with --write, writes it instead), and
#   2. runs the checker on the table.
# A change in ALICE-Law never changes this repository's result by itself. Either step exits 2 when it
# compared nothing or cannot read what it needs (a malformed pin, a fetch that failed), and that fails
# the run like a finding does.
#
# usage: scripts/g11_table.sh [--write]
set -euo pipefail
cd "$(dirname "$0")/.."

mode=--check
if [[ $# -gt 1 || ( $# -eq 1 && "$1" != "--write" ) ]]; then
  echo "usage: scripts/g11_table.sh [--write]" >&2
  exit 2
fi
[[ $# -eq 1 ]] && mode=--write

py=$(command -v python3 || command -v python || true)
if [[ -z "$py" ]]; then
  echo "no python3 or python on PATH" >&2
  exit 2
fi

pin=.github/g11-table-pin
name=$(awk '$1 == "name" { print $2 }' "$pin")
rev=$(awk '$1 == "rev" { print $2 }' "$pin")
checker_sum=$(awk '$1 == "checker-sha256" { print $2 }' "$pin")
gen_sum=$(awk '$1 == "gen-sha256" { print $2 }' "$pin")
if [[ ! "$name" =~ ^ALICE-[A-Za-z0-9-]+$ || ! "$rev" =~ ^[0-9a-f]{40}$ || ! "$checker_sum" =~ ^[0-9a-f]{64}$ \
      || ! "$gen_sum" =~ ^[0-9a-f]{64}$ ]]; then
  echo "$pin: needs 'name ALICE-<repository>', 'rev <40 hex>', 'checker-sha256 <64 hex>' and 'gen-sha256 <64 hex>'" >&2
  exit 2
fi

# ALICE_LAW_URL replaces the repository fetched from (the tests use a local one)
law_url=${ALICE_LAW_URL:-https://github.com/ext-sakamoro/ALICE-Law}
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
git init -q "$tmp/law"
if ! git -C "$tmp/law" fetch -q --depth 1 "$law_url" "$rev"; then
  echo "ALICE-Law $rev: fetch failed" >&2
  exit 2
fi
# the blobs as committed: a checkout with CRLF line ends would change the SHA-256 compared below
if ! git -C "$tmp/law" -c core.autocrlf=false -c core.eol=lf checkout -q FETCH_HEAD; then
  echo "ALICE-Law $rev: checkout failed" >&2
  exit 2
fi
for f in scripts/g11_table_check.py scripts/g11_table_gen.py conformance/g11-shared-rows.toml; do
  if [[ ! -f "$tmp/law/$f" ]]; then
    echo "ALICE-Law $rev: no $f" >&2
    exit 2
  fi
done
sum() { "$py" -c 'import hashlib, sys; print(hashlib.sha256(open(sys.argv[1], "rb").read()).hexdigest())' "$1"; }
for pair in "g11_table_check.py:$checker_sum" "g11_table_gen.py:$gen_sum"; do
  f=${pair%%:*} want=${pair#*:}
  got=$(sum "$tmp/law/scripts/$f")
  if [[ "$got" != "$want" ]]; then
    echo "scripts/$f at $rev has sha256 $got, $pin says $want" >&2
    exit 2
  fi
done

# a pin of this repository that names the same revision (.github/shared-files-pin, .github/public-text-pin)
# is read from this checkout instead of being fetched again
rc=0
"$py" "$tmp/law/scripts/g11_table_gen.py" --repo . --name "$name" --law "$rev=$tmp/law" "$mode" || rc=$?
crc=0
"$py" "$tmp/law/scripts/g11_table_check.py" --repo . --name "$name" --law "$rev=$tmp/law" || crc=$?
if [[ $rc -eq 2 || $crc -eq 2 ]]; then
  exit 2
fi
if [[ $rc -ne 0 || $crc -ne 0 ]]; then
  exit 1
fi
